<template>
	<view class="checkout-page">
		<view v-if="address" class="address-panel" @tap="showAddressPicker=true"><view class="address-mark"><image src="/static/icons/map-pin.png" mode="aspectFit" /></view><view class="address-copy"><view><text>{{ address.receiverName }}</text><text>{{ address.receiverPhone }}</text><text v-if="address.isDefault">默认</text></view><text>{{ address.fullAddress }}</text></view><image class="arrow" src="/static/icons/chevron-right.png" mode="aspectFit" /></view>
		<view v-else class="address-empty" @tap="openAddress"><view class="address-add"><image src="/static/icons/add.png" mode="aspectFit" /></view><view><text>添加收货地址</text><text>下单前需要填写配送信息</text></view><image class="arrow" src="/static/icons/chevron-right.png" mode="aspectFit" /></view>
		<view class="goods-panel"><view class="panel-title">商品清单</view><view v-for="item in items" :key="item.id||item.skuId" class="goods-item"><image :src="item.image||'/static/logo.png'" mode="aspectFill" /><view><text>{{ item.name }}</text><text v-if="item.skuName">{{ item.skuName }}</text><view><text>¥{{ formatPrice(item.price) }}</text><text>× {{ item.quantity }}</text></view></view></view></view>
		<view class="remark-panel"><text>订单备注</text><input v-model.trim="remark" maxlength="100" placeholder="选填，可填写配送要求" /></view>
		<view v-if="mode==='cart'" class="coupon-panel" @tap="showCouponPicker=true"><text>优惠券</text><view><text :class="{muted:!selectedCoupon}">{{ selectedCoupon?`${selectedCoupon.name} · ${couponValue(selectedCoupon)}`:(coupons.length?`${coupons.length} 张可用`:'暂无可用优惠券') }}</text><image src="/static/icons/chevron-right.png" mode="aspectFit" /></view></view>
		<view class="amount-panel"><view><text>商品金额</text><text>¥{{ formatPrice(goodsAmount) }}</text></view><view><text>运费</text><text>¥0.00</text></view><view v-if="discountAmount>0"><text>优惠金额</text><text class="discount">-¥{{ formatPrice(discountAmount) }}</text></view><view class="payable"><text>应付金额</text><text>¥{{ formatPrice(payableAmount) }}</text></view></view>
		<view class="submit-bar"><view><text>共 {{ totalCount }} 件</text><text>合计 ¥{{ formatPrice(payableAmount) }}</text></view><button :disabled="submitting||!items.length||!address" :loading="submitting" @tap="submitOrder">提交订单</button></view>
		<view v-if="showAddressPicker" class="picker-mask" @tap="showAddressPicker=false"><view class="picker-sheet" @tap.stop><view class="picker-head"><text>选择收货地址</text><image src="/static/icons/close.png" mode="aspectFit" @tap="showAddressPicker=false" /></view><scroll-view class="picker-list" scroll-y><view v-for="item in addresses" :key="item.id" class="picker-item" :class="{selected:address?.id===item.id}" @tap="chooseAddress(item)"><view><text>{{ item.receiverName }} {{ item.receiverPhone }}</text><text>{{ item.fullAddress }}</text></view><text>{{ address?.id===item.id?'✓':'' }}</text></view><button @tap="openAddress">管理收货地址</button></scroll-view></view></view>
		<view v-if="showCouponPicker" class="picker-mask" @tap="showCouponPicker=false"><view class="picker-sheet" @tap.stop><view class="picker-head"><text>选择优惠券</text><image src="/static/icons/close.png" mode="aspectFit" @tap="showCouponPicker=false" /></view><scroll-view class="picker-list coupon-picker" scroll-y><view class="picker-item" :class="{selected:!selectedCouponId}" @tap="chooseCoupon(null)"><view><text>不使用优惠券</text><text>按商品原价结算</text></view><text>{{ !selectedCouponId?'✓':'' }}</text></view><view v-for="item in coupons" :key="item.id" class="picker-item" :class="{selected:selectedCouponId===item.id}" @tap="chooseCoupon(item)"><view><text>{{ item.name }} · {{ couponValue(item) }}</text><text>{{ item.minAmount>0?`满 ${formatPrice(item.minAmount)} 元可用`:'无门槛使用' }}</text></view><text>{{ selectedCouponId===item.id?'✓':'' }}</text></view></scroll-view></view></view>
	</view>
</template>

<script>
	import {buyNowOrder,createOrder,getAddressList,getAvailableCoupons,getCart,getMyCoupons,getProductDetail} from '../../api/index.js'
	import {formatMoney} from '../../utils/format.js'
	import {filterUsableCoupons,getCouponDiscount,getCouponValueText,normalizeAddressList,normalizeCartList,normalizeCouponList,normalizeProductDetail} from '../../utils/normalizers.js'
	export default{
		data(){return{mode:'cart',cartIds:[],skuId:0,productId:0,quantity:1,items:[],addresses:[],address:null,remark:'',submitting:false,showAddressPicker:false,showCouponPicker:false,coupons:[],selectedCouponId:null}},
		computed:{goodsAmount(){return this.items.reduce((sum,item)=>sum+item.price*item.quantity,0)},totalCount(){return this.items.reduce((sum,item)=>sum+item.quantity,0)},selectedCoupon(){return this.coupons.find((item)=>item.id===this.selectedCouponId)||null},discountAmount(){return getCouponDiscount(this.selectedCoupon,this.goodsAmount)},payableAmount(){return Math.max(0,this.goodsAmount-this.discountAmount)}},
		onLoad(options){this.mode=options.mode||'cart';this.cartIds=String(options.cartIds||'').split(',').map(Number).filter(Boolean);this.skuId=Number(options.skuId||0);this.productId=Number(options.productId||0);this.quantity=Math.max(1,Number(options.quantity||1));this.loadCheckout()},onShow(){if(this.items.length)this.loadAddresses()},
		methods:{formatPrice:formatMoney,couponValue:getCouponValueText,async loadCheckout(){uni.showLoading({title:'加载中'});try{await Promise.all([this.loadAddresses(),this.loadItems()]);if(this.mode==='cart')await this.loadCoupons()}catch(error){uni.showToast({title:error.message,icon:'none'})}finally{uni.hideLoading()}},async loadAddresses(){this.addresses=normalizeAddressList(await getAddressList());if(!this.address||!this.addresses.some((item)=>item.id===this.address.id))this.address=this.addresses.find((item)=>item.isDefault)||this.addresses[0]||null},async loadItems(){if(this.mode==='buyNow'){const product=normalizeProductDetail(await getProductDetail(this.productId));const sku=product.skuList.find((item)=>item.id===this.skuId);if(!sku)throw new Error('商品规格不存在');this.items=[{skuId:sku.id,name:product.title,skuName:Object.values(sku.specs).join(' / '),image:sku.image||product.images[0],price:sku.price,quantity:this.quantity}]}else{const cart=normalizeCartList(await getCart());this.items=cart.filter((item)=>this.cartIds.includes(item.id));if(!this.items.length)throw new Error('结算商品已失效，请返回购物车重试')}},async loadCoupons(){try{const [mineResult,templateResult]=await Promise.all([getMyCoupons({status:0}),getAvailableCoupons()]);const templates=normalizeCouponList(templateResult,'available');this.coupons=filterUsableCoupons(normalizeCouponList(mineResult,'mine',templates),this.goodsAmount);if(!this.coupons.some((item)=>item.id===this.selectedCouponId))this.selectedCouponId=null}catch{this.coupons=[];uni.showToast({title:'优惠券暂时无法加载',icon:'none'})}},chooseAddress(item){this.address=item;this.showAddressPicker=false},chooseCoupon(item){this.selectedCouponId=item?.id||null;this.showCouponPicker=false},openAddress(){this.showAddressPicker=false;uni.navigateTo({url:'/pages/address/index'})},async submitOrder(){if(!this.address){uni.showToast({title:'请选择收货地址',icon:'none'});return}this.submitting=true;try{const result=this.mode==='buyNow'?await buyNowOrder({skuId:this.skuId,quantity:this.quantity,addressId:this.address.id,remark:this.remark}):await createOrder({cartIds:this.cartIds,addressId:this.address.id,couponId:this.selectedCouponId||undefined,remark:this.remark});const orderNo=result?.orderNo||result?.orderNumber||result;if(!orderNo)throw new Error('订单创建成功但未返回订单号');uni.showToast({title:'订单提交成功',icon:'success'});setTimeout(()=>uni.redirectTo({url:`/pages/payment/index?orderNo=${encodeURIComponent(orderNo)}&amount=${this.payableAmount}`}),500)}catch(error){uni.showToast({title:error.message,icon:'none'})}finally{this.submitting=false}}},
	}
</script>

<style scoped>
	.checkout-page{min-height:100vh;padding:18rpx 20rpx 150rpx;background:#f5f6f8}.address-panel,.address-empty,.goods-panel,.remark-panel,.coupon-panel,.amount-panel{margin-bottom:16rpx;border:1rpx solid #eceef1;border-radius:11rpx;background:#fff}.address-panel{display:flex;padding:26rpx 22rpx;align-items:center}.address-mark,.address-add{display:flex;width:62rpx;height:62rpx;flex:0 0 62rpx;align-items:center;justify-content:center;border-radius:50%;background:#fff0ee}.address-mark image,.address-add image{width:34rpx;height:34rpx}.address-copy{min-width:0;flex:1;margin-left:18rpx}.address-copy view{display:flex;align-items:center;gap:13rpx;color:#30363e;font-size:26rpx;font-weight:700}.address-copy view text:nth-child(2){color:#6b737e;font-size:22rpx;font-weight:400}.address-copy view text:last-child{padding:3rpx 7rpx;border-radius:4rpx;color:#e1251b;background:#fff0ee;font-size:17rpx}.address-copy>text{display:block;margin-top:10rpx;color:#636b76;font-size:23rpx;line-height:1.5}.arrow{width:30rpx;height:30rpx;flex:0 0 30rpx}.address-empty{display:flex;padding:32rpx 24rpx;align-items:center}.address-empty>view:nth-child(2){min-width:0;flex:1;margin-left:18rpx}.address-empty>view:nth-child(2) text{display:block;color:#343a42;font-size:26rpx;font-weight:700}.address-empty>view:nth-child(2) text:last-child{margin-top:8rpx;color:#969da6;font-size:21rpx;font-weight:400}.panel-title{padding:24rpx;border-bottom:1rpx solid #eef0f2;color:#30363e;font-size:27rpx;font-weight:700}.goods-item{display:flex;padding:22rpx;border-bottom:1rpx solid #eff0f2}.goods-item:last-child{border-bottom:0}.goods-item>image{width:140rpx;height:140rpx;flex:0 0 140rpx;border-radius:8rpx;background:#f2f3f5}.goods-item>view{min-width:0;flex:1;margin-left:18rpx}.goods-item>view>text{display:-webkit-box;overflow:hidden;color:#373e47;font-size:25rpx;line-height:34rpx;-webkit-box-orient:vertical;-webkit-line-clamp:2}.goods-item>view>text:nth-child(2){display:block;margin-top:8rpx;color:#969da6;font-size:20rpx;white-space:nowrap}.goods-item>view>view{display:flex;margin-top:18rpx;align-items:center;justify-content:space-between}.goods-item>view>view text:first-child{color:#e1251b;font-size:28rpx;font-weight:800}.goods-item>view>view text:last-child{color:#818994;font-size:21rpx}.remark-panel,.coupon-panel{display:flex;height:92rpx;padding:0 22rpx;align-items:center}.remark-panel>text,.coupon-panel>text{width:140rpx;color:#444b54;font-size:24rpx}.remark-panel input{min-width:0;flex:1;font-size:23rpx}.coupon-panel>view{display:flex;min-width:0;flex:1;align-items:center;justify-content:flex-end}.coupon-panel>view text{max-width:92%;overflow:hidden;color:#e1251b;font-size:22rpx;text-overflow:ellipsis;white-space:nowrap}.coupon-panel>view text.muted{color:#8e959f}.coupon-panel image{width:27rpx;height:27rpx;margin-left:8rpx}.amount-panel{padding:18rpx 22rpx}.amount-panel view{display:flex;padding:10rpx 0;align-items:center;justify-content:space-between;color:#666e78;font-size:23rpx}.amount-panel view text:last-child{color:#333940}.amount-panel .discount{color:#e1251b}.amount-panel .payable{margin-top:10rpx;padding-top:20rpx;border-top:1rpx solid #eef0f2;color:#30363e;font-weight:700}.amount-panel .payable text:last-child{color:#e1251b;font-size:31rpx;font-weight:800}.submit-bar{position:fixed;right:0;bottom:0;left:0;z-index:10;display:flex;min-height:104rpx;padding:0 18rpx env(safe-area-inset-bottom);align-items:center;border-top:1rpx solid #e2e4e7;background:#fff}.submit-bar>view{min-width:0;flex:1;text-align:right}.submit-bar>view text{display:block;color:#8e959f;font-size:20rpx}.submit-bar>view text:last-child{margin-top:4rpx;color:#e1251b;font-size:29rpx;font-weight:800}.submit-bar button{width:220rpx;height:76rpx;margin:0 0 0 20rpx;border:0;border-radius:9rpx;color:#fff;background:#e1251b;font-size:25rpx;line-height:76rpx}.submit-bar button::after{border:0}.submit-bar button[disabled]{color:#fff;background:#c9ccd1}.picker-mask{position:fixed;inset:0;z-index:30;background:rgba(0,0,0,.46)}.picker-sheet{position:absolute;right:0;bottom:0;left:0;border-radius:18rpx 18rpx 0 0;background:#fff}.picker-head{display:flex;height:94rpx;padding:0 28rpx;align-items:center;justify-content:space-between;border-bottom:1rpx solid #eceef1;color:#30363e;font-size:29rpx;font-weight:700}.picker-head image{width:44rpx;height:44rpx;padding:8rpx}.picker-list{max-height:650rpx}.coupon-picker{padding-bottom:calc(20rpx + env(safe-area-inset-bottom))}.picker-item{display:flex;padding:24rpx 28rpx;align-items:center;border-bottom:1rpx solid #eef0f2}.picker-item>view{min-width:0;flex:1}.picker-item>view text{display:block;color:#383f48;font-size:24rpx}.picker-item>view text:last-child{margin-top:9rpx;color:#7a828d;font-size:22rpx;line-height:1.45}.picker-item>text{color:#e1251b;font-size:28rpx}.picker-item.selected{background:#fff8f7}.picker-list button{height:74rpx;margin:20rpx 28rpx calc(20rpx + env(safe-area-inset-bottom));border:1rpx solid #e1251b;border-radius:8rpx;color:#e1251b;background:#fff;font-size:24rpx;line-height:74rpx}.picker-list button::after{border:0}
</style>
